#include <DHT.h>

#define DHT_PIN 2 // Pin for DHT22 sensor
#define Calibration_PIN A0 // Pin for analog input (thermometer or hygrometer)

DHT dht(DHT_PIN, DHT22);

void setup() {
  Serial.begin(9600);
  dht.begin();
}

void loop() {
  int temperature = analogRead(Calibration_PIN); // Read analog input value from thermometer
  float calibration_temperature = (temperature * (5.0 / 1023.0)); // Convert analog value to temperature value
  int humidity = analogRead(Calibration_PIN); // Read analog input value from hygrometer
  float calibration_humidity = (humidity * (5.0 / 1023.0)); // Convert analog value to humidity value

  // Upload the calibration values to the DHT22 sensor
  dht.calibrationTemperature(calibration_temperature);
  dht.calibrationHumidity(calibration_humidity);

  // Wait for a few seconds before taking the next reading
  delay(3000);

  // Start reading the temperature and humidity values from the DHT22 sensor
  int temperature_value = dht.readTemperature();
  int humidity_value = dht.readHumidity();

  // Print the calibration results
  Serial.print("Calibration Temperature: ");
  Serial.println(calibration_temperature);
  Serial.print("Calibration Humidity: ");
  Serial.println(calibration_humidity);
  Serial.print("Temperature Value: ");
  Serial.println(temperature_value);
  Serial.print("Humidity Value: ");
  Serial.println(humidity_value);

  // Wait for a few seconds before taking the next reading
  delay(3000);
}
